        'Keine lesbaren Tabellenblätter.'=>'No readable worksheets.',
        'Das auszufüllende Blatt Mitglieder fehlt oder ist nicht eindeutig.'=>'The Members input worksheet is missing or ambiguous.',
    ];
    public static function key(string$s):string{return 'member_excel_'.substr(hash('sha256',$s),0,24);}
    public static function messages(string$locale):array{$en=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as$s=>$translation)$out[self::key($s)]=$en?$translation:$s;return$out;}
    public static function text(string$s,array$messages,array$values=[]):string{$text=$messages[self::key($s)]??$s;foreach($values as$key=>$value)$text=str_replace('{'.$key.'}',(string)$value,$text);return$text;}
    public static function row(string$s,array$messages):string{if(preg_match('/\AName innerhalb der Datei doppelt; Zeile ([0-9]+) prüfen\.\z/D',$s,$m))return self::text('Name innerhalb der Datei doppelt; Zeile {line} prüfen.',$messages,['line'=>$m[1]]);return self::text($s,$messages);}
}
